    #[test]
    fn exact_wire_directions_capabilities_nonces_and_unknown_opcodes_refuse() {
        for operation in [Operation::Read, Operation::Write] {
            for nonce in [1, u32::MAX - 1] {
                let request = Request::new(operation, nonce).unwrap();
                assert_eq!(Request::decode(&request.encode(), 0), Ok(request));
                assert!(Response::decode(&request.encode(), 0).is_err());
                for outcome in [
                    Outcome::Read,
                    Outcome::Written,
                    Outcome::Refused(Refusal::Denied),
                    Outcome::Refused(Refusal::Malformed),
                    Outcome::Refused(Refusal::Busy),
                    Outcome::Refused(Refusal::Stale),
                    Outcome::Refused(Refusal::Storage),
                    Outcome::Refused(Refusal::Recovery),
                ] {
                    let reply = request.reply(outcome);
                    assert_eq!(reply.nonce(), nonce);
                    assert_eq!(Response::decode(&reply.encode(), 0), Ok(reply));
                    assert!(Request::decode(&reply.encode(), 0).is_err());
                    assert_eq!(
                        Response::decode(&reply.encode(), 1),
                        Err(DecodeError::CapabilityCount)
                    );
                }
            }
        }
        for value in [0, u32::MAX] {
            assert_eq!(
                Request::new(Operation::Read, value),
                Err(DecodeError::Nonce)
            );
            assert_eq!(
                Response::decode(&frame(3, value), 0),
                Err(DecodeError::Nonce)
            );
        }
        for opcode in 0..=255 {
            assert_eq!(
                Request::decode(&frame(opcode, 1), 0).is_ok(),
                matches!(opcode, 1 | 2)
            );
            assert_eq!(
                Response::decode(&frame(opcode, 1), 0).is_ok(),
                matches!(opcode, 3 | 4 | 129..=134)
            );
        }
        for len in 0..=16 {
            if len != 8 {
                assert_eq!(
                    Request::decode(&[0; 16][..len], 0),
                    Err(DecodeError::Length)
                );
            }
        }
        for index in 0..3 {
            let mut bytes = frame(1, 1);
            bytes[index] ^= 0x80;
            assert!(Request::decode(&bytes, 0).is_err());
        }
        assert!(Request::decode(&[b'N', b'D', 1, 1, 1, 0, 0, 0], 0).is_err());
    }
    #[test]
    fn retries_are_only_unaccepted_and_old_ack_cannot_complete_a_new_exchange() {
        let mut client = Client::new();
        let read = client.prepare(Operation::Read, 10, 50).unwrap();
        assert_eq!(client.retry_unaccepted(11), Ok(read));
        assert!(!client.page_available());
        client.accepted(read, 12).unwrap();
        assert!(client.retry_unaccepted(13).is_err());
        assert!(client.prepare(Operation::Write, 13, 60).is_err());
        assert_eq!(
            client.accept(&read.reply(Outcome::Read).encode(), 0, 14, |_| Ok(7)),
            Ok(Completion::Read(7))
        );
        assert!(client.page_available());
        let write = client.prepare(Operation::Write, 15, 70).unwrap();
        assert_eq!(write.nonce(), 2);
        client.accepted(write, 16).unwrap();
        let called = Cell::new(false);
        assert_eq!(
            client.accept(&read.reply(Outcome::Read).encode(), 0, 17, |_| {
                called.set(true);
                Ok(())
            }),
            Err(ClientError::Mismatch)
        );
        assert!(!called.get());
        assert!(client.quarantined());
        assert!(!client.page_available());
        assert!(client.prepare(Operation::Read, 18, 80).is_err());
    }
